  _isExpired(entry) {
    if (entry.ttl === undefined) {
      return false;
    }
    return (this.now() - entry.timestamp) >= entry.ttl;
  }

  get(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return undefined;
    }

    // Get the value and move to end (mark as most recently used)
    const value = entry.value;
    this.map.delete(key);
    this.map.set(key, entry);

    return value;
  }

  has(key) {
    // If key doesn't exist, return false
    if (!this.map.has(key)) {
      return false;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return false;
    }

    return true;
  }

  peek(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the entry and check if it's expired
    const entry = this.map.get(key);
    if (this._isExpired(entry)) {
      this.map.delete(key);
      return undefined;
    }

    // Get the value without updating usage order
    return entry.value;
  }

  size() {
    // Count non-expired entries
    let count = 0;
    for (const entry of this.map.values()) {
      if (!this._isExpired(entry)) {
        count++;
      }
    }
    return count;
  }

  keys() {
    // Return keys in LRU order (most recently used to least recently used)
    // but only for non-expired entries
    const result = [];
    for (const [key, entry] of this.map.entries()) {
      if (!this._isExpired(entry)) {
        result.push(key);
      }
    }
    return result;
  }

  clear() {
    this.map.clear();
  }
}

